user_id = #{userId}, file_name = #{fileName}, file_url = #{fileUrl}, status = #{status}, error_message = #{errorMessage}, create_time = #{createTime}, update_time = #{updateTime}, start_time = #{startTime}, complete_time = #{completeTime}, queue_position = #{queuePosition}, consumer_id = #{consumerId}, execute_duration_ms = #{executeDurationMs}
where task_id = #{taskId}

